#ifndef _CRT_SECURE_NO_WARNINGS
#define _CRT_SECURE_NO_WARNINGS
#endif
#include "database_first_research.hpp"
#include "software_json.hpp"
#include <fstream>

namespace mre { namespace {
void write_file(const fs::path& p,const std::string& s){fs::create_directories(p.parent_path());std::ofstream f(p,std::ios::binary);check(bool(f),"Cannot write "+utf8(p));f<<s;check(bool(f),"Write failed "+utf8(p));}
std::string fp(const std::map<std::string,std::string>& files){uint64_t h=1469598103934665603ULL;for(const auto&[n,v]:files)for(unsigned char c:n+"\n"+v){h^=c;h*=1099511628211ULL;}return std::to_string(h);}
std::map<std::string,std::string> response_files(const fs::path& p){std::map<std::string,std::string> out;std::ifstream f(p,std::ios::binary);if(!f)return out;std::stringstream b;b<<f.rdbuf();try{auto root=software_json::parse(b.str());auto payload=software_json::parse(root.at("choices").array.at(0).at("message").at("content").str());const auto& list=payload.at("files");for(const auto& item:list.array)out[item.at("path").str()]=item.at("content").str();}catch(...){ }return out;}
void build_files(const DatabaseFirstConfig& c,const fs::path& run,const std::map<std::string,std::string>& files,std::string& bs,std::string& rs,std::string& bo,std::string& ro){if(files.empty()){bs="CPP_PROJECT_MISSING";rs="NOT_ATTEMPTED";return;}fs::path project=run/"project";for(const auto&[name,content]:files){fs::path rel(name);check(!rel.is_absolute()&&name.find("..") == std::string::npos,"Unsafe generated path: "+name);write_file(project/rel,content);}if((!fs::is_regular_file(project/"main.cpp")&&!fs::is_regular_file(project/"src"/"main.cpp"))||!fs::is_regular_file(project/"CMakeLists.txt")){bs="CPP_PROJECT_MISSING";rs="NOT_ATTEMPTED";return;}char* raw=nullptr;size_t len=0;_dupenv_s(&raw,&len,"MRE_KR_COMPILER");std::string compiler=raw&&*raw?raw:"F:\\KR_COMPILER\\KR-Portable-CPP-MultiHost_v2.4\\KR-COMPILE.exe";if(raw)free(raw);if(!fs::is_regular_file(compiler)){bs="INFRASTRUCTURE_ERROR";rs="NOT_ATTEMPTED";bo="Missing compiler: "+compiler;return;}auto b=runProcess(shellQuote(compiler)+" --build "+shellQuote(utf8(project))+" --target WINDOWS --configuration Release",c.timeout_ms);bo=b.output;bs=b.timed_out?"BUILD_TIMEOUT":(b.exit_code==0?"BUILD_SUCCEEDED":"BUILD_FAILED");if(b.exit_code!=0||b.timed_out){rs="NOT_ATTEMPTED";return;}fs::path exe;fs::path outdir=project/"KR_BUILD"/"Release";for(const auto& e:fs::directory_iterator(outdir))if(e.is_regular_file()&&e.path().extension()==".exe"){exe=e.path();break;}if(exe.empty()){rs="INFRASTRUCTURE_ERROR";ro="Missing expected executable: "+utf8(exe);return;}auto r=runProcess(shellQuote(utf8(exe))+" --selftest",c.timeout_ms);ro=r.output;rs=r.timed_out?"RUN_TIMEOUT":(r.exit_code==0?"RUN_SUCCEEDED":((r.output.find("Counterexample")!=std::string::npos||r.output.find("FALSIFIED")!=std::string::npos||r.output.find("Hypothesis Holds: FALSE")!=std::string::npos)?"RUN_COMPLETED_WITH_FINDINGS":"RUN_FAILED"));}
}
int completeDatabaseFirstSoftwareResearch(const DatabaseFirstConfig& c){
 int rc=runDatabaseFirstSoftwareResearch(c);Db db(c.research_db);
 Stmt q(db,"SELECT id,response_path,run_id FROM dossiers WHERE status='GEMINI_RESPONSE_ACCEPTED' ORDER BY id");
 while(q.step()){
  int64_t id=q.getInt64(0),run_id=q.getInt64(2);fs::path response=q.getText(1),run=response.parent_path();
  std::string mode="MODEL_HYPOTHESIS_UNVERIFIED",note="No explicit original-mathematics declaration was present; classified conservatively.";
  std::string constructionStatus="AUTONOMOUS_CONSTRUCTION_UNSPECIFIED",constructionName="",sourceOperations="",novelComposition="",applicationGoal="",algorithmSteps="",baselinePlan="",implementedExperiments="",falsificationPlan="",noveltyStatus="UNPROVEN";
  try{std::ifstream f(response,std::ios::binary);std::stringstream b;b<<f.rdbuf();auto envelope=software_json::parse(b.str());auto content=envelope.at("choices").array.at(0).at("message").at("content").str();auto first=content.find_first_not_of(" \t\r\n");if(first!=std::string::npos&&content.compare(first,3,"```")==0){auto eol=content.find("\n",first);auto end=content.rfind("```");if(eol!=std::string::npos&&end>eol)content=content.substr(eol+1,end-eol-1);}auto design=software_json::parse(content);if(design.object.count("research_mode")){mode=design.at("research_mode").str();if(mode!="ORIGINAL_MATHEMATICS"&&mode!="MODEL_HYPOTHESIS")mode="MODEL_HYPOTHESIS_UNVERIFIED";}if(design.object.count("fidelity_note"))note=design.at("fidelity_note").str();}catch(...){ }
  try{std::ifstream f(response,std::ios::binary);std::stringstream b;b<<f.rdbuf();auto envelope=software_json::parse(b.str());auto content=envelope.at("choices").array.at(0).at("message").at("content").str();auto first=content.find_first_not_of(" \t\r\n");if(first!=std::string::npos&&content.compare(first,3,"```")==0){auto eol=content.find("\n",first);auto end=content.rfind("```");if(eol!=std::string::npos&&end>eol)content=content.substr(eol+1,end-eol-1);}auto design=software_json::parse(content);if(design.object.count("construction_status"))constructionStatus=design.at("construction_status").str();if(design.object.count("algorithm_name"))constructionName=design.at("algorithm_name").str();if(design.object.count("source_operations"))sourceOperations=design.at("source_operations").str();if(design.object.count("novel_composition"))novelComposition=design.at("novel_composition").str();if(design.object.count("application_goal"))applicationGoal=design.at("application_goal").str();if(design.object.count("algorithm_steps"))algorithmSteps=design.at("algorithm_steps").str();if(design.object.count("baseline_plan"))baselinePlan=design.at("baseline_plan").str();if(design.object.count("implemented_experiments"))implementedExperiments=design.at("implemented_experiments").str();if(design.object.count("falsification_plan"))falsificationPlan=design.at("falsification_plan").str();if(design.object.count("novelty_status"))noveltyStatus=design.at("novelty_status").str();}catch(...){ }
  {std::ofstream f(run/"RESEARCH_CLASSIFICATION.txt",std::ios::binary);f<<"research_mode="<<mode<<"\nfidelity_note="<<note<<"\nconstruction_status="<<constructionStatus<<"\nalgorithm_name="<<constructionName<<"\nnovelty_status="<<noveltyStatus<<"\n";}
  {std::ofstream f(run/"ALGORITHMIC_CONSTRUCTION.md",std::ios::binary);f<<"# Autonomous Algorithmic Construction\n\n- Status: "<<constructionStatus<<"\n- Name: "<<constructionName<<"\n- Research mode: "<<mode<<"\n- Novelty status: "<<noveltyStatus<<"\n\n## Application goal\n"<<applicationGoal<<"\n\n## Source operations\n"<<sourceOperations<<"\n\n## Novel composition\n"<<novelComposition<<"\n\n## Algorithm steps\n"<<algorithmSteps<<"\n\n## Validation plan\n"<<baselinePlan<<"\n"<<implementedExperiments<<"\n\n## Falsification plan (optional)\n"<<falsificationPlan<<"\n\n## Fidelity note\n"<<note<<"\n";}
  Stmt classify(db,"UPDATE dossiers SET research_mode=?1,fidelity_note=?2 WHERE id=?3");classify.bind(1,mode);classify.bind(2,note);classify.bind(3,id);classify.step();
  if(db.count("SELECT COUNT(*) FROM generated_artifacts WHERE run_id="+std::to_string(run_id))>0){Stmt update(db,"UPDATE generated_artifacts SET research_mode=?1,fidelity_status=?2 WHERE run_id=?3");update.bind(1,mode);update.bind(2,mode=="ORIGINAL_MATHEMATICS"?"DECLARED_UNVERIFIED":"MODEL_OR_INSPIRED");update.bind(3,run_id);update.step();continue;}
  auto files=response_files(response);if(files.empty())continue;std::string bs,rs,bo,ro;build_files(c,run,files,bs,rs,bo,ro);
  Stmt ins(db,"INSERT INTO generated_artifacts(run_id,project_path,source_fingerprint,build_status,run_status,research_mode,fidelity_status,build_output,run_output) VALUES(?1,?2,?3,?4,?5,?6,?7,?8,?9)");ins.bind(1,run_id);ins.bind(2,utf8(run/"project"));ins.bind(3,fp(files));ins.bind(4,bs);ins.bind(5,rs);ins.bind(6,mode);ins.bind(7,mode=="ORIGINAL_MATHEMATICS"?"DECLARED_UNVERIFIED":"MODEL_OR_INSPIRED");ins.bind(8,bo);ins.bind(9,ro);ins.step();std::cout<<"DB_FIRST_ARTIFACT dossier="<<id<<" research_mode="<<mode<<" build_status="<<bs<<" run_status="<<rs<<"\n";
  if(c.require_gemini&&(bs!="BUILD_SUCCEEDED"||(rs!="RUN_SUCCEEDED"&&rs!="RUN_COMPLETED_WITH_FINDINGS")))throw std::runtime_error("Generated artifact validation failed: "+bs+"/"+rs);
 }
 return rc;
}
}
